AND oa_attendance_document_id NOT IN
#{replaced}
AND NOT ( document_type IN ('LEAVE', 'TIME_OFF') AND (
employee_id IN
#{id}
employee_id = #{employeeId}
1 = 1
) )
AND NOT (
employee_id IN
#{id}
employee_id = #{employeeId}
1 = 1
AND ( ( interval_start IS NOT NULL AND interval_start < #{windowEndExclusive} AND interval_end > #{windowStart} ) OR ( point_instant IS NOT NULL AND point_instant >= #{windowStart} AND point_instant < #{windowEndExclusive} ) OR ( document_type IN ('LEAVE', 'TIME_OFF') AND recognized_minutes_by_date_json IS NOT NULL AND recognized_minutes_by_date_json != '' AND recognized_minutes_by_date_json != '{}' AND CONCAT('', recognized_minutes_by_date_json) REGEXP #{recognizedCopyDatePattern} ) OR ( document_type IN ('LEAVE', 'TIME_OFF') AND (recognized_minutes_by_date_json IS NULL OR recognized_minutes_by_date_json = '' OR recognized_minutes_by_date_json = '{}') AND ( (interval_start IS NOT NULL AND interval_start < #{windowEndExclusive} AND interval_end > #{windowStart}) OR (point_instant IS NOT NULL AND point_instant >= #{windowStart} AND point_instant < #{windowEndExclusive}) ) ) ) )

